def prime_table(N):
    is_prime = np.zeros(N, np.int8)
    if N > 2:
        is_prime[2] = 1
    if N > 3:
        is_prime[3::2] = 1
    limit = int(N ** 0.5) + 1
    for p in range(3, limit, 2):
        if is_prime[p]:
            is_prime[p * p:N:p] = 0
    return is_prime, np.flatnonzero(is_prime)

def main(N, primes):
    div = np.ones(N + 1, dtype=np.int64)
    for p in primes:
        for i in range(N // p + 1):
            div[p * i] += div[i]
    div *= np.arange(N + 1, dtype=np.int64)
    return int(div.sum())

