import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    edges = [(data[i] - 1, data[i + 1] - 1) for i in range(2, 2 + 2 * M, 2)]

    if M == 0:
        sys.stdout.write("0")
        return

    ans = 0
    parent = [0] * N
    size = [0] * N

    for skip in range(M):
        for i in range(N):
            parent[i] = i
            size[i] = 1

        comp = N
        for j in range(M):
            if j == skip:
                continue
            a, b = edges[j]

            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            while parent[b] != b:
                parent[b] = parent[parent[b]]
                b = parent[b]

            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]
                comp -= 1
                if comp == 1:
                    break

        r0 = 0
        while parent[r0] != r0:
            parent[r0] = parent[parent[r0]]
            r0 = parent[r0]

        for x in range(1, N):
            y = x
            while parent[y] != y:
                parent[y] = parent[parent[y]]
                y = parent[y]
            if y != r0:
                ans += 1
                break

