def divisors(n):
    x = n
    fac = []
    cnt = []
    p = 2
    while p * p <= x:
        if x % p == 0:
            c = 0
            while x % p == 0:
                x //= p
                c += 1
            fac.append(p)
            cnt.append(c)
        p = 3 if p == 2 else p + 2
    if x > 1:
        fac.append(x)
        cnt.append(1)

    res = [1]
    for p, c in zip(fac, cnt):
        base = res[:]
        mul = 1
        for _ in range(c):
            mul *= p
            for v in base:
                res.append(v * mul)
    res.sort()
    return res

def main():
    n = I()
    a = LI()

    cand = set()
    add = cand.add
    for i in range(n, 0, -1):
        d = divisors(i)
        ld = len(d)
        lim = 1 << ld
        for mask in range(1, lim):
            c = []
            ok = True
            for k in range(ld):
                if mask >> k & 1:
                    x = d[k]
                    for e in c:
                        if x % e == 0:
                            ok = False
                            break
                    if not ok:
                        break
                    c.append(x)
            if ok:
                add(tuple(c + [n + 1]))

    b = sorted(cand, reverse=True)
    arr = a
    idxs = range(1, n + 1)

    for c in b:
        t = 0
        for j in idxs:
            aj = arr[j - 1]
            if aj:
                for e in c:
                    if j % e == 0:
                        t += aj
                        break
        if t < 0:
            for j in idxs:
                for e in c:
                    if j % e == 0:
                        arr[j - 1] = 0
                        break

    return sum(arr)

