    N, K = data[0], data[1]
    A = data[2:2 + N]
    F = data[2 + N:2 + 2 * N]

    A.sort(reverse=True)
    F.sort()

    upper_bound = max(a * f for a, f in zip(A, F))
    lower_bound = 0

    while lower_bound <= upper_bound:
        mid = (lower_bound + upper_bound) // 2
        s = 0
        for a, f in zip(A, F):
            v = mid // f
            if a > v:
                s += a - v
        if s <= K:
            upper_bound = mid - 1
        else:
            lower_bound = mid + 1

