import sys

class UnionFind:
    __slots__ = ("parents",)

    def __init__(self, n):
        self.parents = [-1] * n

    def find(self, x):
        parents = self.parents
        while parents[x] >= 0:
            p = parents[x]
            if parents[p] >= 0:
                parents[x] = parents[p]
            x = p
        return x

    def union(self, x, y):
        parents = self.parents
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        if parents[x] > parents[y]:
            x, y = y, x
        parents[x] += parents[y]
        parents[y] = x

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M = data[0], data[1]
    edge = [(data[i] - 1, data[i + 1] - 1) for i in range(2, 2 + 2 * M, 2)]

    ans = 0
    for i in range(M):
        uf = UnionFind(N)
        for j in range(M):
            if j != i:
                a, b = edge[j]
                uf.union(a, b)
        if sum(1 for p in uf.parents if p < 0) >= 2:
            ans += 1

    print(ans)

if __name__ == "__main__":
    main()

