from math import isqrt

def prime_factorize(num):
    prime_factor = {}
    cnt = 0
    while num % 2 == 0:
        num //= 2
        cnt += 1
    if cnt:
        prime_factor[2] = cnt

    i = 3
    limit = isqrt(num)
    while i <= limit and num > 1:
        if num % i == 0:
            cnt = 0
            while num % i == 0:
                num //= i
                cnt += 1
            prime_factor[i] = cnt
            limit = isqrt(num)
        i += 2

    if num > 1:
        prime_factor[num] = 1

    return prime_factor

def comb(n, r, R):
    a = R.get(n)
    if a is None:
        a = 1
        for x in range(2, n + 1):
            a *= x
        R[n] = a

    b = R.get(n - r)
    if b is None:
        b = 1
        for x in range(2, n - r + 1):
            b *= x
        R[n - r] = b

    c = R.get(r)
    if c is None:
        c = 1
        for x in range(2, r + 1):
            c *= x
        R[r] = c

    return a // (b * c)

