def gen_d_prim(n):
    D = [n + 1 if i & 1 else 2 for i in range(n + 1)]
    if n >= 0:
        D[0] = 0
    if n >= 1:
        D[1] = 0
    limit = int(n ** 0.5)
    for i in range(3, limit + 1, 2):
        if D[i] != n + 1:
            continue
        step = i
        start = i * i
        for j in range(start, n + 1, step):
            if D[j] == n + 1:
                D[j] = i
    for i in range(3, n + 1, 2):
        if D[i] == n + 1:
            D[i] = i
    return D

def is_pairwise(A):
    D = gen_d_prim(10**6)
    past = set()
    for a in A:
        now = set()
        while a != 1:
            p = D[a]
            if p in past and p not in now:
                return False
            now.add(p)
            past.add(p)
            a //= p
    return True

def gcd_all(A):
    g = 0
    for a in A:
        g = gcd(g, a)
    return g

