import sys


class BinaryIndexedTree:
    __slots__ = ("n", "node", "data")

    def __init__(self, A):
        n = len(A)
        self.n = n
        node = [0] * (n + 1)
        data = [0] * (n + 1)
        s = 0
        for i in range(1, n + 1):
            a = A[i - 1]
            s += a
            data[i] = a
            node[i] = s - (s - (i & -i))
        self.node = node
        self.data = data

    def add(self, i, v):
        node = self.node
        n = self.n
        while i <= n:
            node[i] += v
            i += i & -i

    def sum(self, i):
        node = self.node
        rst = 0
        while i > 0:
            rst += node[i]
            i -= i & -i
        return rst

    def get(self, i, j):
        if i == j:
            return self.data[i]
        return self.sum(j) - self.sum(i - 1)


